#pragma once
// Game functions found by signature when the mod starts, so a patch that only moves code needs no update. Source code
// names a function by its address in the reference build (game build 1287369); those numbers are keys and never change.
// map_natives_table.h is generated by tools/patchcheck/gensig.py from tools/native_pins.txt. Signatures run at least 64
// bytes where the function does, with the game's struct offsets literal, so a layout change turns the feature off.
//
// On a build this version wasn't made for, a session that dies before two minutes of play keeps these features off on
// that build at the next start (greeneye\unlock-map-markers\untested-build.txt: delete it to try again).
#include <windows.h>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>
#include "greeneye.h"
#include "map_natives_table.h"

namespace map_natives {
constexpr uint32_t kReferenceStamp = 0x6aeb144c, kReferenceSize = 0x2a3f000;

struct Entry {
    const char* name;
    const char* signature;
    uint32_t offset;
    bool follow;
    uint32_t key;
    uint8_t* found;
};
#define MAP_NATIVE_ENTRY(name, signature, offset, follow, key) {#name, signature, offset, follow != 0, key, nullptr},
inline Entry g_entries[] = {MAP_NATIVE_TABLE(MAP_NATIVE_ENTRY)};
#undef MAP_NATIVE_ENTRY
inline bool g_resolved = false, g_tripped = false, g_armed = false;

inline IMAGE_NT_HEADERS64* Nt() {
    auto* exe = reinterpret_cast<uint8_t*>(GetModuleHandleW(nullptr));
    return reinterpret_cast<IMAGE_NT_HEADERS64*>(exe + reinterpret_cast<IMAGE_DOS_HEADER*>(exe)->e_lfanew);
}

// The reference build, or the same image with Steam's DRM wrapper (.bind) stripped off, which only shortens it.
inline bool KnownBuild() {
#ifdef UMM_DEV_BRIDGE
    // Dev builds can act as if the game had been patched.
    if (GetFileAttributesA(greeneye::DataPath("pretend-untested.txt")) != INVALID_FILE_ATTRIBUTES) return false;
#endif
    auto* nt = Nt();
    if (nt->FileHeader.TimeDateStamp != kReferenceStamp) return false;
    if (nt->OptionalHeader.SizeOfImage == kReferenceSize) return true;
    if (nt->OptionalHeader.SizeOfImage > kReferenceSize) return false;
    const auto* section = IMAGE_FIRST_SECTION(nt);
    for (WORD i = 0; i < nt->FileHeader.NumberOfSections; ++i)
        if (std::memcmp(section[i].Name, ".bind", 6) == 0) return false;
    return true;
}

inline void WriteGuard(const char* state) {
    FILE* f = nullptr;
    if (fopen_s(&f, greeneye::DataPath("untested-build.txt"), "wb") == 0 && f) {
        std::fprintf(f, "%08lx %s\n", Nt()->FileHeader.TimeDateStamp, state);
        std::fclose(f);
    }
}

inline void CheckCrashGuard(const GreeneyeHost* host) {
    if (KnownBuild()) return;
    char line[64]{};
    FILE* f = nullptr;
    if (fopen_s(&f, greeneye::DataPath("untested-build.txt"), "rb") == 0 && f) {
        std::fread(line, 1, sizeof(line) - 1, f);
        std::fclose(f);
    }
    char stamp[16];
    std::snprintf(stamp, sizeof(stamp), "%08lx ", Nt()->FileHeader.TimeDateStamp);
    const bool same = std::strncmp(line, stamp, 9) == 0;
    if (same && std::strstr(line, "ok")) return;
    if (same && std::strstr(line, "running") && host->generation <= 1) { // a later generation is a reload
        g_tripped = true;
        return;
    }
    WriteGuard("running");
    g_armed = true;
}

// Once per generation, in one pass over the code as it was before any hook.
inline void Ensure(const GreeneyeHost* host, void (*log)(const char*, ...)) {
    if (g_resolved) return;
    g_resolved = true;
    CheckCrashGuard(host);
    if (g_tripped) {
        if (log) log("Native features: the last session on this untested game build ended early, so they stay off on it; delete untested-build.txt to try again");
        return;
    }
    auto* exe = reinterpret_cast<uint8_t*>(GetModuleHandleW(nullptr));
    auto* nt = Nt();
    uint8_t* text = nullptr;
    size_t size = 0;
    const auto* section = IMAGE_FIRST_SECTION(nt);
    for (WORD i = 0; i < nt->FileHeader.NumberOfSections; ++i) {
        if (std::memcmp(section[i].Name, ".text", 6) == 0) {
            text = exe + section[i].VirtualAddress;
            size = section[i].Misc.VirtualSize;
        }
    }
    if (!text || !host->read) return;
    std::vector<uint8_t> code(size);
    host->read(text, code.data(), size);
    const size_t count = sizeof(g_entries) / sizeof(g_entries[0]);
    std::vector<std::vector<int>> patterns(count);
    std::vector<uint32_t> bucket[256];
    size_t longest = 0;
    for (size_t i = 0; i < count; ++i) {
        for (const char* p = g_entries[i].signature; *p;) {
            while (*p == ' ') ++p;
            if (!*p) break;
            if (*p == '?') {
                patterns[i].push_back(-1);
            } else {
                const char hex[3]{p[0], p[1], 0};
                patterns[i].push_back(static_cast<int>(std::strtoul(hex, nullptr, 16)));
            }
            p += 2;
        }
        bucket[patterns[i][0]].push_back(static_cast<uint32_t>(i));
        if (patterns[i].size() > longest) longest = patterns[i].size();
    }
    std::vector<const uint8_t*> hit(count, nullptr);
    std::vector<uint8_t> hits(count, 0);
    for (size_t at = 0; at + longest <= size; ++at) {
        for (uint32_t i : bucket[code[at]]) {
            const auto& pattern = patterns[i];
            size_t k = 1;
            while (k < pattern.size() && (pattern[k] < 0 || code[at + k] == pattern[k])) ++k;
            if (k == pattern.size()) {
                hit[i] = code.data() + at;
                if (hits[i] < 2) ++hits[i];
            }
        }
    }
    std::string missing;
    for (size_t i = 0; i < count; ++i) {
        auto& e = g_entries[i];
        uint8_t* live = nullptr;
        if (hits[i] == 1) live = text + (hit[i] - code.data());
        else if (!hits[i] && host->find) live = host->find(e.signature, nullptr); // behind another mod's hook
        if (live) {
            live += e.offset;
            if (e.follow) {
                uint8_t call[5]{};
                host->read(live, call, 5);
                int32_t delta = 0;
                std::memcpy(&delta, call + 1, 4);
                live = call[0] == 0xe8 ? live + 5 + delta : nullptr;
            }
        }
        e.found = live;
        if (!live) {
            if (!missing.empty()) missing += ' ';
            missing += e.name;
        }
    }
    if (log) {
        if (missing.empty()) log("Native features: all %zu functions found%s", count, KnownBuild() ? "" : " on this untested game build");
        else log("Native features: %s not found; what needs them stays off", missing.c_str());
    }
}

inline uint8_t* At(uint32_t referenceRva) {
    for (const auto& e : g_entries)
        if (e.key == referenceRva) return e.found;
    return nullptr;
}

inline void NoteStablePlay() {
    if (!g_armed) return;
    g_armed = false;
    WriteGuard("ok");
}
} // namespace map_natives
